import argparse,json,shutil
from pathlib import Path
from .data import write,sha,stamp


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);root=p.parse_args().root.resolve();out=root/'outputs/atlas_pair_holding_v1';completed=json.loads((out/'completed.json').read_text());assert completed['no_promotion'];results=json.loads((out/'results.json').read_text());development=json.loads((out/'development.json').read_text());selection=json.loads((out/'selection.json').read_text());protocol=json.loads((out/'protocol.json').read_text());paired=json.loads((out/'paired_trade_audit.json').read_text());audit=json.loads((out/'independent_audit.json').read_text());assert audit['all_pass']
    def trim(v):
        if isinstance(v,dict):return {k:trim(x) for k,x in v.items() if k not in ['curve','cash_curve']}
        if isinstance(v,list):return [trim(x) for x in v]
        return v
    package=dict(generated_utc=stamp(),results=trim(results),development=trim(development),selection=selection,protocol=protocol,completion=completed,paired_trade_audit=paired,ledger_and_quote_audit=trim(audit),opportunity=json.loads((out/'opportunity_audit.json').read_text()),independent_validation=False,paper_account_changed=False)
    write(out/'aggregate_results.json',package);fmt=lambda v:f'{v:,.2f}';money=lambda v:('−$' if v<0 else '+$')+fmt(abs(v));row=lambda values:'<tr>'+''.join('<td>'+str(v)+'</td>' for v in values)+'</tr>'
    table=''.join(row([r['cost'].title(),money(r['comparison']['old_net']),money(r['comparison']['new_net']),money(r['comparison']['net_delta']),fmt(r['comparison']['old_drawdown'])+'%',fmt(r['comparison']['new_drawdown'])+'%',fmt(r['metrics']['annualized_extrapolation_pct'])+'%',r['metrics']['trades'],fmt(r['metrics']['win_rate'])+'%',paired[r['cost']]['pnl_changed']]) for r in results)
    dev=''.join(row([r['profile'],r['cost'],money(r['metrics']['net_pnl']),fmt(r['account']['quote_drawdown_pct'])+'%',r['metrics']['trades']]) for r in development)
    monthly=100*((1+results[0]['metrics']['annualized_extrapolation_pct']/100)**(1/12)-1)
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trade Dashboard</title><style>body{margin:0;background:#0b1320;color:#e5edf8;font:14px/1.65 "Segoe UI",sans-serif}main{max-width:1400px;margin:auto;padding:40px}h1{font-size:36px}p{color:#aab9ce}section{padding:25px;background:#142133;border:1px solid #293b53;border-radius:15px;margin:22px 0}.badge{color:#59deb0;letter-spacing:.1em;font-size:12px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}td,th{text-align:right;border-bottom:1px solid #293b53;padding:13px}td:first-child,th:first-child{text-align:left}th{color:#aab9ce}a{color:#80b7ff}.notice{border-left:3px solid #f4cf82;padding:15px;background:#f4cf8209}summary{cursor:pointer;color:#80b7ff}</style><main><span class="badge">PROJECT ATLAS · PAPER ONLY · NO PROMOTION</span><h1>Trade Dashboard</h1><p>SPX500 15m at1.5R + NAS10015m at2R · $5,000 shared account</p><div class="notice">Development-selected lead: Nasdaq holding deadline90minutes instead of60; SPX unchanged. All entries, natural stops, RR targets and risk limits unchanged. Full-period prices previously exposed. Small modeled improvement, not independent repeatability.</div><section><h2>Profit increased and quote drawdown declined at all three costs</h2><p>15 Dec2025–30 Oct2026 ·320calendar days. Annualization is extrapolation, not an annual track record. Gains depend on only6–7changed exits per scenario; no new trade identities or sizes were introduced.</p><div class="scroll"><table><thead><tr><th>Costs</th><th>Previous net</th><th>90min NAS net</th><th>Delta</th><th>Previous DD</th><th>New DD</th><th>Annualized*</th><th>Trades</th><th>Win rate</th><th>Changed P&amp;Ls</th></tr></thead><tbody>TABLE</tbody></table></div></section><section><h2>20–30% monthly is not supported by this evidence</h2><p>The current standard-cost full-period return equates to approximately MONTHLY% per month geometrically; this is not a stable monthly payout. On$5,000,20–30% in one month requires$1,000–$1,500 net,or40–60units of the maximum$25 planned trade risk. Compounding20% monthly for12months would produce approximately792% annual return;30% monthly approximately2,230%. The approved risk limits are unchanged.</p><p>The latest standard-cost annualized extrapolation is13.72%,not20–30% annually or monthly. Higher/severe costs reduce that further. No claim that either target is achieved or independently reliable.</p></section><section><h2>Bounded comparison and evidence</h2><p>Six fixed management profiles: NAS90/NAS120,SPX90/SPX120,both90/both120. Each runs at all3costs on development history plus3unchanged controls. NAS90 was frozen as lead before its June–October continuation. Only that lead was continued; other later combinations were not searched. All dates had already been exposed by earlier research,so this is not untouchedOOS or true walk-forward validation.</p><p>Only management expiry changed, from actual observed entry+60minutes to90/120minutes on the specified lane, capped16:00NewYork. Target/stop logic and entry conditions stayfixed. Original development controls exactly match the prefix of preserved prior full ledgers. New lead netP&amp;L and full quote drawdown independently reconstructed. Entries and quantities match the prior book at every cost.</p><details><summary>All21development records, including failures</summary><div class="scroll"><table><thead><tr><th>Profile</th><th>Costs</th><th>Development net</th><th>Quote DD</th><th>Trades</th></tr></thead><tbody>DEVELOPMENT</tbody></table></div></details></section><section><h2>Opportunity capture and risk</h2><p>Standard-cost baseline had131NAS and5SPX candidate decisions vetoed solely for capital/exposure restrictions after other entry gates passed. These are not proven winning opportunities. Most raw minimum-lot vetoes overlap failed feature/direction gates; counting every raw veto as a missed profitable trade would be wrong. No minimum-lot or risk rule is bypassed.</p><p>Risk remains min(0.5% equity,$25) all-in pertrade,1% grosscombinedopen,2% daily-loss entrypause,10% peak-DD entrypause,no arbitrary countquota. Standard/higher/severe costs retain observed spreads scaled1/1.5/2×,roundtrip fees$6/$12/$18 per full CFDlot,1/2/4ticks per side;severe adds1second exit delay and2× marginproxy. Fees,historical clock,contract/margin and liquidity remain uncertain. Stop/entrypause levels do not guarantee realized losses or drawdown.</p><p>Next evidence: freeze a complete receipt-clock evaluator before financially scoring a new cohort; compare fixed candidate to contemporaneous fixed control. Existing collector and paper-forward book are unchanged. No further selection on these reused later prices.</p><p><a href="aggregate_results.json">Aggregate records</a></p></section></main></html>'''.replace('TABLE',table).replace('MONTHLY',fmt(monthly)).replace('DEVELOPMENT',dev)
    (out/'report.html').write_text(html,encoding='utf-8');preview=root/'outputs/atlas_two_strategy_exits_v1/holding_comparison.html';preview.write_text(html.replace('href="aggregate_results.json"','href="http://127.0.0.1:8893/holding_aggregate_results.json"'),encoding='utf-8');shutil.copy2(out/'aggregate_results.json',preview.with_name('holding_aggregate_results.json'))
    dest=root/'work/tradingbot/research/atlas-pair-holding/2026-11-02';dest.mkdir(parents=True,exist_ok=True);shutil.copy2(out/'report.html',dest/'index.html');shutil.copy2(out/'aggregate_results.json',dest/'aggregate_results.json');(dest/'README.md').write_text('''# Atlas fixed-RR holding-clock comparison\n\nSPX50015m1.5R plus NAS10015m2R,shared5000USD paper account. Entries,stops,RR and approved risk limits unchanged. Six fixed90/120minute management profiles,21developmentrecords includingcontrols,then one selected lead continued through reused later history. All originals and failures preserved locally.\n\nNAS90 lead: standardnet596.27/quoteDD2.81606percent;higher361.38/3.30575;severe284.97/2.89718. Dates2025-12-15–2026-10-30.6–7trade PnLs changed percost,no entry/quantity changes. Positive development screen does not establish independent reliability.13.72percent standard annualized extrapolation remains below20–30percent annual target.20–30percent monthly is unsupported.\n\nAll results are reused-history,not untouchedOOS or prospective validation. No deployment,liveorders,riskchanges or extra strategies. Aggregate outputs only,rawprices/privateledgers local. Source atlas_exit_research/holding_pair.py; report holding_pair_report.py. Completed-output guards prevent identical reruns.\n''',encoding='utf-8');write(out/'report_identity.json',dict(created_utc=stamp(),html_sha256=sha(out/'report.html'),aggregate_sha256=sha(out/'aggregate_results.json'),financial_engine_changed=False))


